const form = document.getElementById('contact-form');
const errorSummary = document.getElementById('error-summary');
const errorList = document.getElementById('error-list');
const successAlert = document.getElementById('success-alert');

form.addEventListener('submit', (e) => {
  e.preventDefault();

  const errors = [];
  const nameField = document.getElementById('name-field');
  const stateField = document.getElementById('state-field');
  const termsField = document.getElementById('terms-field');

  if (!nameField.value) {
    nameField.showError = true;
    nameField.errorMessage = 'Full name is required.';
    errors.push({ id: 'name-field', message: 'Full name is required.' });
  } else {
    nameField.showError = false;
  }

  if (!stateField.value) {
    stateField.showError = true;
    stateField.errorMessage = 'Select a state.';
    errors.push({ id: 'state-field', message: 'Select a state.' });
  } else {
    stateField.showError = false;
  }

  if (!termsField.checked) {
    termsField.showError = true;
    termsField.errorMessage = 'You must agree to the terms.';
    errors.push({ id: 'terms-field', message: 'You must agree to the terms.' });
  } else {
    termsField.showError = false;
  }

  if (errors.length > 0) {
    errorList.innerHTML = errors
      .map((err) => `<li><a href="#${err.id}">${err.message}</a></li>`)
      .join('');
    errorSummary.hidden = false;
    successAlert.hidden = true;
    errorSummary.scrollIntoView({ behavior: 'smooth' });
  } else {
    errorSummary.hidden = true;
    successAlert.hidden = false;
  }
});
